#include "myalloc.h"
#include <stdio.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    int op;
    int a;
    int b;
    int c;
} Op;

static unsigned char *ptrs[600];
static size_t sizes[600];

static void fill_pattern(unsigned char *p, size_t n, int seed) {
    size_t lim = n < 64 ? n : 64;
    for (size_t i = 0; i < lim; i++) {
        p[i] = (unsigned char)((seed + i * 13) & 0xFF);
    }
}

static void check_pattern(const unsigned char *p, size_t lim, int seed, int step) {
    for (size_t i = 0; i < lim; i++) {
        unsigned char exp = (unsigned char)((seed + i * 13) & 0xFF);
        if (p[i] != exp) {
            printf("DATA CORRUPTION at step %d byte %zu: got %u expected %u\n", step, i, p[i], exp);
            return;
        }
    }
}

